CREATE TABLE departments (
  dept_id    NUMBER PRIMARY KEY,
  dept_name  VARCHAR2(30) NOT NULL
);

CREATE TABLE employees (
  emp_id     NUMBER PRIMARY KEY,
  emp_code   CHAR(6),
  emp_name   VARCHAR2(50) NOT NULL,
  dept_id    NUMBER,
  salary     NUMBER(10,2),
  hire_date  DATE
);

INSERT INTO departments VALUES (10, 'Sales');
INSERT INTO departments VALUES (20, 'Finance');
INSERT INTO departments VALUES (30, 'IT');

INSERT INTO employees VALUES (101, 'E101', 'Asha Rao',    10, 52000, DATE '2023-04-10');
INSERT INTO employees VALUES (102, 'E102', 'Ravi Kumar',  20, 61000, DATE '2022-11-01');
INSERT INTO employees VALUES (103, 'E103', 'Meena Iyer',  30, 75000, DATE '2021-07-19');
INSERT INTO employees VALUES (104, 'E104', 'John Mathew', 40, 48000,
       TO_DATE('2024-01-15 09:30', 'YYYY-MM-DD HH24:MI'));
COMMIT;

SET SERVEROUTPUT ON

DECLARE
  l_name employees.emp_name%TYPE;
BEGIN
  SELECT emp_name INTO l_name
    FROM employees
   WHERE emp_id = 999;
  DBMS_OUTPUT.PUT_LINE('Name: ' || l_name);
END;
/

DECLARE
  l_name employees.emp_name%TYPE;
BEGIN
  BEGIN
    SELECT emp_name INTO l_name
      FROM employees
     WHERE emp_id = 999;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      l_name := 'Unknown';
  END;

  DBMS_OUTPUT.PUT_LINE('Name: ' || l_name);
END;
/

DECLARE
  l_ids  SYS.ODCINUMBERLIST := SYS.ODCINUMBERLIST(101, 999, 103);
  l_name employees.emp_name%TYPE;
BEGIN
  FOR i IN 1 .. l_ids.COUNT LOOP
    BEGIN
      SELECT emp_name INTO l_name
        FROM employees
       WHERE emp_id = l_ids(i);
      DBMS_OUTPUT.PUT_LINE(l_ids(i) || ': ' || l_name);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE(l_ids(i) || ': not found, skipped');
    END;
  END LOOP;
END;
/

CREATE OR REPLACE FUNCTION get_salary (p_emp_id IN NUMBER)
  RETURN NUMBER
IS
  l_salary employees.salary%TYPE;
BEGIN
  SELECT salary INTO l_salary
    FROM employees
   WHERE emp_id = p_emp_id;
  RETURN l_salary;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR(-20010,
      'Employee ' || p_emp_id || ' not found');
END;
/

SELECT get_salary(999) FROM dual;

DECLARE
  l_name employees.emp_name%TYPE;
BEGIN
  SELECT MAX(emp_name) INTO l_name
    FROM employees
   WHERE emp_id = 999;

  DBMS_OUTPUT.PUT_LINE('Name: ' || NVL(l_name, 'Unknown'));
END;
/

DECLARE
  CURSOR c_emp IS
    SELECT emp_name FROM employees WHERE emp_id = 999;
  l_name employees.emp_name%TYPE;
BEGIN
  OPEN c_emp;
  FETCH c_emp INTO l_name;
  IF c_emp%NOTFOUND THEN
    DBMS_OUTPUT.PUT_LINE('No employee with that ID');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Name: ' || l_name);
  END IF;
  CLOSE c_emp;
END;
/

DECLARE
  TYPE t_names IS TABLE OF employees.emp_name%TYPE;
  l_names t_names;
BEGIN
  SELECT emp_name BULK COLLECT INTO l_names
    FROM employees
   WHERE dept_id = 50;

  DBMS_OUTPUT.PUT_LINE('Rows found: ' || l_names.COUNT);
END;
/

DECLARE
  l_code VARCHAR2(6) := 'E101';
  l_name employees.emp_name%TYPE;
BEGIN
  SELECT emp_name INTO l_name
    FROM employees
   WHERE emp_code = l_code;
  DBMS_OUTPUT.PUT_LINE('Name: ' || l_name);
END;
/

CREATE OR REPLACE FUNCTION get_dept_name (p_dept_id IN NUMBER)
  RETURN VARCHAR2
IS
  l_name departments.dept_name%TYPE;
BEGIN
  SELECT dept_name INTO l_name FROM departments WHERE dept_id = p_dept_id;
  RETURN l_name;
END;
/

SELECT emp_name, get_dept_name(dept_id) AS dept_name
  FROM employees
 ORDER BY emp_id;

DECLARE
  l_dept departments.dept_name%TYPE;
BEGIN
  l_dept := get_dept_name(40);
  DBMS_OUTPUT.PUT_LINE('Dept: ' || l_dept);
END;
/

DECLARE
  TYPE t_dept_map IS TABLE OF VARCHAR2(30) INDEX BY PLS_INTEGER;
  l_depts t_dept_map;
BEGIN
  l_depts(10) := 'Sales';
  l_depts(20) := 'Finance';
  DBMS_OUTPUT.PUT_LINE(l_depts(40));
END;
/

